import numpy as np
def firth(X, y, iters=100):
    X1 = np.column_stack([np.ones(len(y)), np.asarray(X, float)]); y = np.asarray(y, float)
    b = np.zeros(X1.shape[1])
    for _ in range(iters):
        mu = 1/(1 + np.exp(-X1 @ b)); W = mu*(1 - mu); I = X1.T @ (X1*W[:, None])
        h = W*np.einsum('ij,jk,ik->i', X1, np.linalg.inv(I), X1)
        b = b + np.linalg.solve(I, X1.T @ (y - mu + h*(0.5 - mu)))
    return b, np.sqrt(np.diag(np.linalg.inv(I)))
beta, se = firth(X, y); OR = np.exp(beta); ci = np.exp(beta - 1.96*se)

