import numpy as np
def km_rmst(t, e, tau):
    times, inv = np.unique(t, return_inverse=True); dd = np.bincount(inv, weights=e)
    nr = len(t) - np.concatenate([[0], np.cumsum(np.bincount(inv))[:-1]])
    S = np.cumprod(1 - dd/nr)
    return float(np.sum(np.concatenate([[1.0], S]) * np.diff(np.minimum(np.concatenate([[0.0], times, [tau]]), tau))))
